/* Stemma del docente, dal suo template. In linea: un'immagine esterna bloccherebbe le tele aperte da file */
window.Stemma = (function () {
  const img = new Image();
  const pronto = new Promise((ok) => { img.onload = ok; img.onerror = ok; });
  img.src = 'data:image/png;base64,';
  return { img, pronto };
})();
